<#
.SYNOPSIS
    Invoke-ScopedScan — run an external scanner against ONLY the Azure-derived in-scope
    targets for the External Vulnerability Agent (EVA).

.DESCRIPTION
    EVA may only ever touch hosts that map back to an in-scope Azure resource. This wrapper
    is the single sanctioned way to launch a third-party scanner: it derives the target list
    exclusively from the engagement allowlist

        engagements/<session>/scope/external-targets.json

    (generated by tools/external/build-targets.mjs), writes a plain host/URL list next to it,
    and feeds the scanner ONLY that list. It also re-checks the authorization gate locally
    (mode + external_testing.enabled + authorization) before doing anything.

    Defense in depth: even if this wrapper were bypassed, the redteam-guardrails egress hook
    independently blocks any probe to a host that is not on the allowlist and verifies the
    contents of any scanner target-list file. This wrapper just makes the safe path easy.

    NOTHING here is on by default and the scanner itself must be installed separately.

.PARAMETER Tool
    Which scanner to run: nuclei | httpx | nikto | whatweb | testssl | zap-baseline.

.PARAMETER Cwd
    Repository root (where engagement.yaml and engagements/ live). Defaults to current dir.

.PARAMETER Session
    Session directory name or path under engagements/. Defaults to the active session
    recorded in engagements/.current-session.

.PARAMETER ExtraArgs
    Additional arguments passed through to the scanner (after the scoped target list).

.PARAMETER DryRun
    Print the exact command(s) that would run, but do not execute them.

.EXAMPLE
    pwsh tools/external/Invoke-ScopedScan.ps1 -Tool nuclei -ExtraArgs '-t','http/misconfiguration'

.EXAMPLE
    pwsh tools/external/Invoke-ScopedScan.ps1 -Tool testssl -DryRun
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('nuclei', 'httpx', 'nikto', 'whatweb', 'testssl', 'zap-baseline')]
    [string]$Tool,

    [string]$Cwd = '.',

    [string]$Session,

    [string[]]$ExtraArgs = @(),

    [switch]$DryRun
)

$ErrorActionPreference = 'Stop'

function Fail([string]$msg) {
    Write-Error "Invoke-ScopedScan refused to run: $msg"
    exit 2
}

$repoRoot = (Resolve-Path -LiteralPath $Cwd).Path

# --- Resolve the active session + allowlist ---------------------------------------------
if (-not $Session) {
    $marker = Join-Path $repoRoot 'engagements/.current-session'
    if (-not (Test-Path -LiteralPath $marker)) {
        Fail "no active session (engagements/.current-session is missing). Run New-Session.ps1 first."
    }
    $Session = (Get-Content -LiteralPath $marker -Raw).Trim()
}
if ([System.IO.Path]::IsPathRooted($Session)) {
    $sessionDir = (Resolve-Path -LiteralPath $Session).Path
} elseif ($Session -match '[\\/]') {
    $sessionDir = (Resolve-Path -LiteralPath (Join-Path $repoRoot $Session)).Path
} else {
    $sessionDir = Join-Path $repoRoot (Join-Path 'engagements' $Session)
}
$allowlistPath = Join-Path $sessionDir 'scope/external-targets.json'
if (-not (Test-Path -LiteralPath $allowlistPath)) {
    Fail "no allowlist at $allowlistPath. Generate it: node tools/external/build-targets.mjs --db <db> --session $sessionDir"
}

# --- Re-check the authorization gate locally (the egress hook also enforces this) -------
$engagementYaml = Join-Path $repoRoot 'engagement.yaml'
if (-not (Test-Path -LiteralPath $engagementYaml)) {
    Fail "engagement.yaml not found at repo root; active external testing requires an authorized engagement."
}
$yamlText = Get-Content -LiteralPath $engagementYaml -Raw

$mode = $null
if ($yamlText -match '(?m)^\s*mode:\s*[''"]?([\w-]+)') { $mode = $Matches[1] }
if ($mode -ne 'external-active-testing') {
    Fail "engagement mode is '$mode'; active external probing requires mode: external-active-testing."
}

# Pull the external_testing block (best-effort, no YAML dependency).
$etBlock = ''
$lines = $yamlText -split "`r?`n"
$capture = $false
foreach ($line in $lines) {
    if ($line -match '^external_testing\s*:') { $capture = $true; continue }
    if ($capture) {
        if ($line -match '^\S' -and $line.Trim() -ne '') { break }
        $etBlock += "$line`n"
    }
}
if ($etBlock -notmatch '(?m)^\s*enabled:\s*[''"]?(true|yes|on|1)\b') {
    Fail "external_testing.enabled is not true in engagement.yaml."
}
if ($etBlock -notmatch '(?m)^\s*attested_by:\s*[''"]?\S') {
    Fail "external_testing.authorization.attested_by is not set in engagement.yaml."
}
if ($etBlock -notmatch '(?m)^\s*attestation_id:\s*[''"]?\S') {
    Fail "external_testing.authorization.attestation_id is not set in engagement.yaml."
}

# --- Materialize plain host/URL lists from the allowlist JSON ----------------------------
$doc = Get-Content -LiteralPath $allowlistPath -Raw | ConvertFrom-Json
$hosts = @()
$urls = @()
if ($doc.allowlist) {
    if ($doc.allowlist.hosts) { $hosts += $doc.allowlist.hosts }
    if ($doc.allowlist.ips) { $hosts += $doc.allowlist.ips }
}
if ($doc.targets) {
    foreach ($t in $doc.targets) {
        if ($t.url) { $urls += $t.url } elseif ($t.host) { $urls += "https://$($t.host)/" }
    }
}
$hosts = $hosts | Sort-Object -Unique
$urls = $urls | Sort-Object -Unique
if (-not $hosts -or $hosts.Count -eq 0) {
    Fail "the allowlist is empty — there are no in-scope external targets to scan."
}

$scopeDir = Join-Path $sessionDir 'scope'
$hostsFile = Join-Path $scopeDir 'targets.hosts.txt'
$urlsFile = Join-Path $scopeDir 'targets.urls.txt'
$header = "# Generated by Invoke-ScopedScan from external-targets.json — DO NOT EDIT BY HAND"
Set-Content -LiteralPath $hostsFile -Value (@($header) + $hosts) -Encoding utf8
Set-Content -LiteralPath $urlsFile -Value (@($header) + $urls) -Encoding utf8

Write-Host "Scope: $($hosts.Count) host(s) from $allowlistPath" -ForegroundColor Cyan
Write-Host "Host list: $hostsFile" -ForegroundColor DarkGray

# --- Build the scanner invocation(s), scoped to the generated list -----------------------
# File-based tools get the scope file; per-host tools are looped (each host arg is also
# independently validated by the egress guardrail).
$invocations = @()
switch ($Tool) {
    'nuclei'       { $invocations += , (@('nuclei', '-l', $hostsFile) + $ExtraArgs) }
    'httpx'        { $invocations += , (@('httpx', '-l', $hostsFile) + $ExtraArgs) }
    'testssl'      { $invocations += , (@('testssl.sh', '--file', $hostsFile) + $ExtraArgs) }
    'whatweb'      { $invocations += , (@('whatweb', "--input-file=$hostsFile") + $ExtraArgs) }
    'nikto'        { foreach ($h in $hosts) { $invocations += , (@('nikto', '-h', $h) + $ExtraArgs) } }
    'zap-baseline' { foreach ($u in $urls) { $invocations += , (@('zap-baseline.py', '-t', $u) + $ExtraArgs) } }
}

$exe = $invocations[0][0]
if (-not (Get-Command $exe -ErrorAction SilentlyContinue)) {
    Write-Warning "'$exe' is not installed / not on PATH. Showing the scoped command(s) instead:"
    $DryRun = $true
}

foreach ($inv in $invocations) {
    $display = ($inv | ForEach-Object { if ($_ -match '\s') { '"' + $_ + '"' } else { $_ } }) -join ' '
    if ($DryRun) {
        Write-Host "DRYRUN: $display"
        continue
    }
    Write-Host "RUN: $display" -ForegroundColor Green
    & $inv[0] @($inv[1..($inv.Count - 1)])
}
